import{_ as d,o as r,c as a,a2 as e}from"./chunks/framework.DXRWYp4X.js";const m=JSON.parse('{"title":"25 · 算法军械库（操练册）","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://R2h1.github.io/fullstack-learning-site/25-算法军械库"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"25 · 算法军械库（操练册） | 全栈 × AI 学习路径"}],["meta",{"property":"og:description","content":"面试级 · 生产级 · 企业级的全栈 + AI 学习课程（个人笔记，内容优先）"}],["meta",{"property":"og:url","content":"https://R2h1.github.io/fullstack-learning-site/25-算法军械库"}],["meta",{"name":"twitter:card","content":"summary"}]]},"headers":[],"relativePath":"25-算法军械库.md","filePath":"25-算法军械库.md","lastUpdated":1793294125000}'),o={name:"25-算法军械库.md"};function i(l,t,n,h,s,c){return r(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="_25-·-算法军械库-操练册" tabindex="-1">25 · 算法军械库（操练册） <a class="header-anchor" href="#_25-·-算法军械库-操练册" aria-label="Permalink to &quot;25 · 算法军械库（操练册）&quot;">​</a></h1><blockquote><p>达标目标：<strong>14 类题型地图 + 模板肌肉记忆，100 天达成「medium 20 分钟 AC 率 &gt;70%」；大厂算法轮的唯一解法是刷够且有统计，没有捷径。</strong> 一句话理由：这是国内大厂门票，八股和作品再好，算法挂一面就进不了二面——而站点现状是力扣/DP/图论提及次数为 <strong>0</strong>，必须开新线。 衔接：20 章（每日轨道的算法 30–45 min）、18 章（手写题清单——那是前端轮加餐，本章才是算法轮本体）、01 章（Promise 并发控制题的思路复用）。 ⚠️ 操练册：一切以统计数据为准（AC 率/用时分布），「刷完了」不进入验收。</p></blockquote><hr><h2 id="_1-与前端手写题的分工-别混淆两个战场" tabindex="-1">1. 与前端手写题的分工（别混淆两个战场） <a class="header-anchor" href="#_1-与前端手写题的分工-别混淆两个战场" aria-label="Permalink to &quot;1. 与前端手写题的分工（别混淆两个战场）&quot;">​</a></h2><ul><li><strong>18 章手写题</strong>（debounce/deepClone/Promise/响应式）：前端面的工程轮，考 API 级熟练度，1–2 周集中过</li><li><strong>本章</strong>：算法轮，考的是问题归约能力，靠 100 天持续喂养</li><li>交叉点：LRU（双链表+Map）、并发限制（BFS/队列思想）、虚拟滚动（滑动窗口+二分）——面试里能用算法语言讲手写题，是加分项</li></ul><h2 id="_2-题型地图-14-类-每类给「判定信号-→-模板-→-大厂高频」" tabindex="-1">2. 题型地图（14 类，每类给「判定信号 → 模板 → 大厂高频」） <a class="header-anchor" href="#_2-题型地图-14-类-每类给「判定信号-→-模板-→-大厂高频」" aria-label="Permalink to &quot;2. 题型地图（14 类，每类给「判定信号 → 模板 → 大厂高频」）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>题型</th><th>判定信号</th><th>模板核心</th><th>高频代表作</th></tr></thead><tbody><tr><td>1</td><td>滑动窗口</td><td>连续子数组/子串 + 最优</td><td>右扩左缩 + 计数哈希</td><td>最小覆盖子串、无重复最长子串</td></tr><tr><td>2</td><td>二分</td><td>有序/答案单调性</td><td>左右闭区间 + 去重边界</td><td>旋转数组、二分答案（珂珂吃香蕉）</td></tr><tr><td>3</td><td>快慢指针</td><td>环/原地/第 K</td><td>相遇条件推导</td><td>相交链表、链表排序</td></tr><tr><td>4</td><td>树 DFS/BFS</td><td>递归结构天然</td><td>前中后序 + 层序模板</td><td>最近公共祖先、路径和族</td></tr><tr><td>5</td><td>回溯</td><td>枚举所有组合/排列</td><td>选择→递归→撤销</td><td>子集族、N 皇后、单词搜索</td></tr><tr><td>6</td><td>DP·线性</td><td>最优 + 无后效</td><td>状态定义三步法</td><td>打家劫舍、最长递增子序列</td></tr><tr><td>7</td><td>DP·背包</td><td>选或不选 + 容量</td><td>一维滚动 + 遍历序</td><td>零钱兑换、分割等和子集</td></tr><tr><td>8</td><td>DP·区间</td><td>合并/回文结构</td><td><code>dp[i][j]</code> 按长度枚举</td><td>戳气球、最长回文子序列</td></tr><tr><td>9</td><td>图·遍历</td><td>网络/依赖关系</td><td>BFS/DFS + visited</td><td>岛屿族、克隆图</td></tr><tr><td>10</td><td>拓扑排序</td><td>先修/依赖顺序</td><td>入度表 + 队列</td><td>课程表、最小编号序列</td></tr><tr><td>11</td><td>并查集</td><td>动态连通性</td><td>路径压缩 + 按秩</td><td>账户合并、冗余连接</td></tr><tr><td>12</td><td>堆/TopK</td><td>第 K/前 K</td><td>优先队列模板</td><td>前 K 高频、中位数流</td></tr><tr><td>13</td><td>单调栈</td><td>下一个更大/左右边界</td><td>存下标 + 弹出时机</td><td>每日温度、柱状图最大矩形</td></tr><tr><td>14</td><td>位运算/数学</td><td>奇偶/幂集/整除</td><td>异或性质、lowbit</td><td>只出现一次的数字、Pow(x)</td></tr></tbody></table><p><strong>用法</strong>：每类先精做 3 题吃透模板，再按「判定信号」盲分类 20 题（只归类不写码，练识别速度）——大厂面试前 30 秒的题型识别决定成败。</p><h2 id="_3-语言与代码规范" tabindex="-1">3. 语言与代码规范 <a class="header-anchor" href="#_3-语言与代码规范" aria-label="Permalink to &quot;3. 语言与代码规范&quot;">​</a></h2><ul><li>主语言 <strong>Python</strong>（最短表达，与 21 章共用）；准备一门第二语言即可（TS/Go），别在算法轮展示炫技</li><li>固定答题骨架：读题复述 → 举例验证理解 → 报思路与复杂度 → 写码 → 自测边界（空/单元素/重复/极值）——<strong>这个流程本身就是面试信号</strong></li><li>每 AC 一题写一行「卡点归因」（没想到模型/实现 bug/边界漏），周汇总出弱项榜</li></ul><h2 id="_4-100-天轨道-每天-30–45-min-并入-20-章算法轨道" tabindex="-1">4. 100 天轨道（每天 30–45 min，并入 20 章算法轨道） <a class="header-anchor" href="#_4-100-天轨道-每天-30–45-min-并入-20-章算法轨道" aria-label="Permalink to &quot;4. 100 天轨道（每天 30–45 min，并入 20 章算法轨道）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>天</th><th>量</th><th>内容</th><th>里程碑</th></tr></thead><tbody><tr><td>1–20</td><td>1 新 + 1 复</td><td>滑窗/二分/链表/树 模板四件套</td><td>模板盲写 &lt;10 min</td></tr><tr><td>21–50</td><td>1 新 + 1 复</td><td>DP 线性/背包 + 回溯</td><td>30 题，弱项榜首次清零</td></tr><tr><td>51–75</td><td>1 新 + 1 复</td><td>图/拓扑/并查集/堆/单调栈</td><td>75 题，medium 均时 &lt;25 min</td></tr><tr><td>76–100</td><td>2 新 + 1 复（模拟日）</td><td>混合随机 + 每周一场限时模拟</td><td>100 题，<strong>20 分钟 AC 率 &gt;70%</strong></td></tr></tbody></table><p>复习规则：艾宾浩斯简化版——做错的题第 1/3/7/21 天重做；<strong>重做以「能否口述模型」为过，不以「写出」为过</strong>（面试多是口述后写码）。 周统计入库（截图进 journal），月度复盘按 20 章模板。</p><h2 id="_5-大厂高频补充层-100-题之后的-50-题" tabindex="-1">5. 大厂高频补充层（100 题之后的 50 题） <a class="header-anchor" href="#_5-大厂高频补充层-100-题之后的-50-题" aria-label="Permalink to &quot;5. 大厂高频补充层（100 题之后的 50 题）&quot;">​</a></h2><ul><li>字节/腾讯/阿里近一年高频榜按公司分池各刷 15（题单动态更新，别背三年前的榜单）</li><li>设计题专池：LRUCache、SkipList、RateLimiter、TimeMap、Trie——设计题是工程背景候选人的主场，AC 后追问「怎么分布式化」正好接 22 章</li><li>并发题专池（前端相关）：Promise 并发限流、带取消的任务编排、读写锁——与 01/06/16 章打通</li></ul><h2 id="_6-面试高频题速答-元问题" tabindex="-1">6. 面试高频题速答（元问题） <a class="header-anchor" href="#_6-面试高频题速答-元问题" aria-label="Permalink to &quot;6. 面试高频题速答（元问题）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>题</th><th>速答要点</th></tr></thead><tbody><tr><td>你怎么准备算法</td><td>题型地图 + 判定信号 + 100 天统计（报 AC 率与均时，不报刷题量）</td></tr><tr><td>遇到没见过的题</td><td>归约：先试四类母模型（窗口/二分/图遍历/DP），再退化到暴力+剪枝讲清</td></tr><tr><td>为什么 AC 了还问思路</td><td>面试考沟通与建模，写码只是验证——所以固定骨架先报思路</td></tr></tbody></table><h2 id="_7-达标标准" tabindex="-1">7. 达标标准 <a class="header-anchor" href="#_7-达标标准" aria-label="Permalink to &quot;7. 达标标准&quot;">​</a></h2><p><strong>门票线（阶段一末）：</strong></p><ul><li>[ ] 100 题入库，medium 20 分钟 AC 率 ≥70%，有周统计</li><li>[ ] 14 类模板全部盲写过关（每类 1 道新题 10 分钟内建模）</li></ul><p><strong>强化线（阶段三）：</strong></p><ul><li>[ ] 高频补充层 50 题 + 设计/并发两池全清</li><li>[ ] 每周限时模拟持续，录屏复盘 ≥10 场</li></ul>',22)])])}const p=d(o,[["render",i]]);export{m as __pageData,p as default};
